#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* create_node(int data) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return NULL;
    n->data = data;
    n->next = NULL;
    return n;
}

void insert_head(Node** head, int data) {
    Node* n = create_node(data);
    n->next = *head;
    *head = n;
}

void insert_tail(Node** head, int data) {
    Node* n = create_node(data);
    if (!*head) { *head = n; return; }
    Node* cur = *head;
    while (cur->next) cur = cur->next;
    cur->next = n;
}

void print_list(const Node* head) {
    const Node* cur = head;
    while (cur) {
        printf("%d -> ", cur->data);
        cur = cur->next;
    }
    puts("NULL");
}

void free_list(Node** head) {
    Node* cur = *head;
    while (cur) {
        Node* nxt = cur->next;
        free(cur);
        cur = nxt;
    }
    *head = NULL;
}

int main(void) {
    Node* head = NULL;
    insert_tail(&head, 20);
    insert_tail(&head, 30);
    insert_head(&head, 10);
    insert_tail(&head, 40);

    printf("Singly Linked List: ");
    print_list(head);

    free_list(&head);
    return 0;
}

