    last->next = n;
    (*head)->prev = n;
}

void dc_display(const Node* head) {
    if (!head) return;
    const Node* cur = head;
    printf("Doubly Circular: ");
    do {
        printf("%d <=> ", cur->data);
        cur = cur->next;
    } while (cur != head);
    puts("(head)");
}

void dc_cleanup(Node** head) {
    if (!head || !*head) return;
    Node* cur = *head;
    Node* last = (*head)->prev;
    while (cur != last) {
        Node* nxt = cur->next;
        free(cur);
        cur = nxt;
    }
    free(last);
    *head = NULL;
}

int main(void) {
    Node* head = NULL;
    dc_insert(&head, 11);
    dc_insert(&head, 22);
    dc_insert(&head, 33);
    dc_display(head);
    dc_cleanup(&head);
    return 0;
}
```

