#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Trie {
    struct Trie* children[26];
    bool is_word;
} Trie;

Trie* trie_create(void) {
    return (Trie*)calloc(1, sizeof(Trie));
}

void trie_add(Trie* root, const char* w) {
    Trie* cur = root;
    for (int i = 0; w[i]; i++) {
        int idx = w[i] - 'a';
        if (!cur->children[idx]) cur->children[idx] = trie_create();
        cur = cur->children[idx];
    }
    cur->is_word = true;
}

bool trie_has(const Trie* root, const char* w) {
    const Trie* cur = root;
    for (int i = 0; w[i]; i++) {
        int idx = w[i] - 'a';
        if (!cur->children[idx]) return false;
        cur = cur->children[idx];
    }
    return cur && cur->is_word;
}

int main(void) {
    Trie* root = trie_create();
    trie_add(root, "apple");
    trie_add(root, "app");

    printf("Search 'app':   %s
