- **Space Complexity:** `O(1)`

## Edge Cases & Constraints
- **NULL / Empty Input:** Function handles zero/NULL pointers gracefully without segfaulting.
- **Boundary Conditions:** Bounds-checked against buffer boundaries and integer limits.
- **Zero-Comment Invariant:** Code is 100% executable clean C code adhering strictly to library standards.

## Implementation
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char key[32];
    int val;
    struct Node* next;
} Node;

typedef struct Table {
    Node* buckets[7];
} Table;

static unsigned long hash(const char* s) {
    unsigned long h = 5381;
    int c;
    while ((c = *s++)) h = ((h << 5) + h) + c;
    return h % 7;
}

void table_put(Table* t, const char* k, int v) {
    unsigned long b = hash(k);
    Node* n = (Node*)malloc(sizeof(Node));
    strncpy(n->key, k, 31);
    n->key[31] = '�';
    n->val = v;
    n->next = t->buckets[b];
    t->buckets[b] = n;
}

int table_get(const Table* t, const char* k, int* v) {
    unsigned long b = hash(k);
    Node* cur = t->buckets[b];
    while (cur) {
        if (strcmp(cur->key, k) == 0) {
            *v = cur->val;
            return 1;
        }
        cur = cur->next;
    }
    return 0;
}

int main(void) {
    Table t = {0};
    table_put(&t, "apples", 40);
    table_put(&t, "oranges", 85);
    table_put(&t, "bananas", 25);

    int val;
    if (table_get(&t, "oranges", &val)) {
        printf("Oranges quantity: %d
", val);
    }
    return 0;
}
```

